        content: `
      GENERAL OUTPATIENT CLINIC
      
      Patient Seen
      
      A 3-year-old female from Ibadan, Oyo State, Yoruba, accompanied by her mother who is a reliable informant.
      
      PC:
      Watery stooling × 3 days.
      Vomiting × 2 days.
      Fever × 2 days.
      
      HPC:
      The patient was apparently well until three days prior to presentation when she developed frequent watery, non-bloody and non-mucoid loose stools occurring approximately 5–6 times daily. The stools were large in volume and yellowish in colour.
      
      Two days prior to presentation, she developed non-projectile vomiting of recently ingested meals occurring about three times daily. There was an associated history of subjective low-grade fever which was continuous and temporarily relieved with Paracetamol syrup.
      
      No history of cough.
      No fast breathing.
      No convulsions.
      No skin rash.
      No ingestion of stale food.
      No similar illness among household members.
      
      The mother administered Oral Rehydration Solution (ORS) at home; however, the child vomited part of it. Because of worsening weakness and poor oral intake, she was brought to the hospital.
      
      ROS:
      
      Gastrointestinal:
      As stated above.
      No abdominal distension.
      
      CNS:
      Irritable but conscious.
      No convulsions.
      No neck stiffness.
      
      Respiratory:
      No cough.
      No fast breathing.
      No chest indrawing.
      
      CVS:
      No cold extremities.
      Capillary refill time normal.
      
      Genitourinary:
      Passed urine about 4 hours before presentation.
      Urine normal in colour.
      
      PMH:
      No previous hospital admissions.
      Immunization up-to-date according to the National Programme on Immunization schedule, including Rotavirus vaccine.
      Developmental milestones appropriate for age.
      No known chronic medical illness.
      No sickle cell disease.
      
      Drug History:
      Paracetamol syrup (125 mg/5 mL), 5 mL three times daily prior to presentation.
      Home-prepared ORS, approximately half a cup after each loose stool, partially tolerated.
      No antibiotics.
      No herbal medications.
      No known drug allergies.
      
      Family and Social History:
      Second child in a monogamous family with three children.
      Parents are traders.
      Lives in a rented apartment in Ibadan with shared pit latrine facilities.
      Domestic water source is a protected well.
      Drinking water is commercially packaged sachet water.
      
      O/E:
      Acutely ill-looking child.
      Irritable.
      Febrile (38.1°C).
      Moderately dehydrated with restlessness, moderately sunken eyes, drinks eagerly when offered fluids and skin pinch returns slowly (<2 seconds).
      Not pale.
      Not jaundiced.
      No peripheral lymphadenopathy.
      No pedal oedema.
      
      Vitals:
      Temperature: 38.1°C
      Pulse Rate: 124 bpm, regular
      Respiratory Rate: 28 cpm
      SpO₂: 98% on room air
      Weight: 14 kg
      
      Abdomen:
      Flat and moves with respiration.
      Soft.
      Mild generalized tenderness.
      No organomegaly.
      Hyperactive bowel sounds (8–10/min).
      
      CVS:
      S1 and S2 heard only.
      No murmurs.
      Capillary refill time <2 seconds.
      
      Respiratory:
      Chest clinically clear.
      Vesicular breath sounds bilaterally.
      No adventitious sounds.
      
      CNS:
      Conscious.
      Irritable but easily consolable.
      No signs of meningeal irritation.
      Normal muscle tone and reflexes.
      
      ASS:
      Acute watery diarrhoea (acute gastroenteritis) with some dehydration.
      
      DDX:
      Viral gastroenteritis (Rotavirus/Adenovirus).
      Malaria with gastrointestinal manifestations.
      Food poisoning (toxin-mediated).
      
      INVESTIGATIONS:
      Stool Microscopy, Culture and Sensitivity.
      Malaria Rapid Diagnostic Test and/or Blood Film for Malaria Parasites.
      Serum Electrolytes, Urea and Creatinine.
      Full Blood Count.
      
      PLAN:
      
      Rehydration (WHO Plan B):
      Administer ORS 75 mL/kg over 4 hours.
      
      Dose:
      75 × 14 kg = 1050 mL over 4 hours.
      
      Administer small frequent amounts using a clean cup and spoon.
      If vomiting occurs, stop for 10 minutes and resume more slowly.
      Reassess hydration status after 4 hours.
      If dehydration resolves, continue WHO Plan A.
      If severe dehydration develops, commence WHO Plan C with intravenous fluids.
      
      Medications:
      Zinc Sulfate 20 mg orally once daily for 10–14 days.
      
      Paracetamol syrup 15 mg/kg/dose orally every 6 hours as required for fever.
      
      Dose:
      15 × 14 kg = 210 mg.
      
      Using 120 mg/5 mL syrup:
      Approximately 9 mL per dose.
      
      Antibiotics:
      Routine antibiotics are not indicated for non-bloody acute watery diarrhoea.
      If Stool MCS identifies a bacterial pathogen such as Vibrio cholerae or Shigella, or if systemic sepsis develops, commence:
      Oral Ciprofloxacin 15 mg/kg twice daily for 3 days.
      
      OR
      
      Oral Azithromycin 10 mg/kg once daily for 3 days.
      
      Nutrition and Supportive Care:
      Continue age-appropriate feeding once vomiting improves.
      Encourage easily digestible nutritious foods such as pap (ogi), bananas and boiled potatoes.
      Continue ORS after every loose stool.
      Maintain good hand hygiene.
      Use safe drinking water.
      Ensure proper disposal of faeces.
      
      Monitoring:
      Monitor temperature, pulse rate and respiratory rate.
      Monitor stool frequency.
      Monitor vomiting episodes.
      Monitor urine output.
      Reassess hydration status regularly.
      
      Referral:
      Refer urgently if severe dehydration develops, persistent vomiting prevents oral rehydration, altered consciousness occurs or signs of systemic sepsis develop.
      Stabilize with intravenous Ringer's Lactate or Normal Saline before transfer where indicated.
      `,
